import { Container, Grid, Typography, Card, CardContent } from "@mui/material";
import "./Skill.css";
import React from "react";
import phpIcon from "../../assets/icons/php.svg";
import jsIcon  from "../../assets/icons/javascript.svg";
import pythonIcon from "../../assets/icons/python.svg";
import CPlusIcon from "../../assets/icons/cplusplus.svg";
import laravelIcon from "../../assets/icons/laravel.svg";
import codeIgniterIcon from "../../assets/icons/codeigniter.svg";
import reactIcon from "../../assets/icons/react.svg";
import bootstrapIcon from "../../assets/icons/bootstrap.svg";
import materialUiIcon from "../../assets/icons/material-ui-seeklogocom.svg";
import tailwindIcon from "../../assets/icons/tailwindcss.svg";
import vscodeIcon from "../../assets/icons/visualstudiocode.svg";
import {Github as GithubLogo} from "../../assets/icons/github.svg";
import gitlabicon from "../../assets/icons/gitlab.svg";
import adobeXDIcon from "../../assets/icons/adobexd.svg";
import composerIcon from "../../assets/icons/composer.svg";
import htmlIcon from "../../assets/icons/html5.svg";
import javaIcon from "../../assets/icons/java.svg";
import mySqlIcon from "../../assets/icons/mysql.svg";
import gitIcon from "../../assets/icons/git.svg";

export default function Skill() {
  const skills = {
    "Programming Languages": [
      {
        name: "PHP",
        icon: (
          <img src={phpIcon} alt="PHP" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Java",
        icon: (
          <img src={javaIcon} alt="Java" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "JavaScript",
        icon: (
          <img src={jsIcon} alt="JavaScript" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Python",
        icon: (
          <img src={pythonIcon} alt="Python" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "C++",
        icon: (
          <img src={CPlusIcon} alt="C++" style={{ height: "1.4rem" }} />
        ),
      },
    ],
    "Back End": [
      {
        name: "Laravel",
        icon: (
          <img src={laravelIcon} alt="Laravel" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Code Igniter",
        icon: (
          <img src={codeIgniterIcon} alt="Code Igniter" style={{ height: "1.4rem" }} />
        ),
      },
    ],
    "Front End": [
      {
        name: "React JS",
        icon: (
          <img src={reactIcon} alt="React JS" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Bootstrap",
        icon: (
          <img src={bootstrapIcon} alt="Bootstrap" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Material UI",
        icon: (
          <img src={materialUiIcon} alt="Material UI" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Tailwinds",
        icon: (
          <img src={tailwindIcon} alt="Tailwinds" style={{ height: "1.4rem" }} />
        ),
      },
    ],
    Tools: [
      {
        name: "Git",
        icon: (
          <img src={gitIcon} alt="Git" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Visual Studio Code",
        icon: (
          <object data={vscodeIcon} type="image/svg+xml" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Github",
        icon: (
          <GithubLogo />
        ),
      },
      {
        name: "GitLab",
        icon: (
          // <svg className="icon icon-gitlab">
          //   <use xlinkHref="#icon-gitlab"></use>
          // </svg>
          <img src={gitlabicon} alt="GitLab" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "MySQL",
        icon: (
          <img src={mySqlIcon} alt="MySQL" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Adobe XD",
        icon: (
          <img src={adobeXDIcon} alt="Adobe XD" style={{ height: "1.4rem" }} />
        ),
      },
      {
        name: "Composer",
        icon: (
          <img src={composerIcon} alt="Composer" style={{ height: "1.4rem" }} />
        ),
      },
    ],
  };
  const nameArray = ["Programming Languages", "Back End", "Front End", "Tools"];

  return (
      <Container
        id={"skills"}
        style={{
          paddingTop: "9rem",
          paddingBottom: "2rem",
          marginBottom: "2rem",
          borderRadius: "10px",
          marginLeft: "auto",
          marginRight: "auto",
        }}
      >
        <Typography
          variant="h2"
          sx={{
            fontWeight: "bold",
            fontSize: "3rem",
            color: "text",
            marginBottom: "1rem",
            textAlign: "center",
          }}
        >
          Skills
        </Typography>
        <Grid justify="center" container spacing={1} alignItems="center">
          {nameArray.map((name, index) => (
            <Grid item xs={12} sm={6} md={4} lg={3} xl={3} key={index}>
              <Card
                sx={{
                  width: 280,
                  height: 350,
                  marginTop: "1rem",
                  marginBottom: "1rem",
                  marginLeft: "auto",
                  marginRight: "auto",
                  boxShadow: "0px 0px 10px 0px rgba(0,0,0,0.2)",
                  borderRadius: "10px",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "",
                  alignItems: "left",
                  padding: "0.5rem",
                  position: "relative",
                }}
              >
                <CardContent>
                  <Typography
                    value={name}
                    sx={{
                      fontWeight: "bold",
                      fontSize: "1.5rem",
                      color: "text",
                      marginBottom: "1.5rem",
                      textAlign: "left",
                    }}
                  >
                    {name}
                  </Typography>
                    {skills[nameArray[index]].map((skill) => (
                      <Grid container spacing={3} key={skill.name}>
                        <Grid item>
                          <Typography align="left">
                            {skill.icon}
                          </Typography>
                        </Grid>
                        <Grid item>
                          <Typography align="left">
                            {skill.name}
                          </Typography>
                        </Grid>
                      </Grid>
                    ))}
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
  );
}
